#include<bits/stdc++.h>
using namespace std;
int n,k;
int c[200005];
signed main(){
    cin>>n>>k;
    int m=n;
    for(int i=1;i<=n;i++){
        cin>>c[i];
        int f=0;
        int l=0;
        bool d[200005]={0};
        if(i-k+1>0){
            for(int j=i-1;j+l>i-k&&j>0;j--){
                if(c[j]==0){
                    l++;
                    continue;
                }
                if(c[j]==c[i]){
                    f++;
                    c[j]=0;
                    d[j]=1;
                }
                else{
                    f=0;
                    break;
                }
            }
            if(f==k-1){
                c[i]=0;
                m-=k;
            }else{
                l=0;
                for(int j=i;j+l>i-k&&j>0;j--){
                    if(d[j])
                        c[j]=c[i];
                    if(!d[j]&&c[j]==0)
                        l++;
                }
            }
        }
        
    }
    cout<<m<<'\n';
    for(int i=1;i<=n;i++)
        if(c[i])
            cout<<c[i]<<' ';
    return 0;
}
